    if(site==='security'&&view==='home')return `<div class="d-console-layout"><aside class="d-console-rail"><div class="d-console-avatar">SL</div><b>${t('My protection','我的保护')}</b>${[['home','▦',t('Dashboard','仪表板')],['scan','◉',t('Security alerts','安全警报')],['threat','▣',t('Device security','设备安全')],['support','?',t('Help & support','帮助与支持')]].map(([v,i,l])=>a(v,`<span>${i}</span>${l}`,v==='home'?'active':'')).join('')}<div class="d-console-session">${t('SESSION','会话')}<br>SL-2048<br><small>${t('Web protection','网页保护')}</small></div></aside><section><div class="d-console-title"><div><h1>${t('Protection overview','保护概览')}</h1><p>${t('Current browser session · Last checked just now','当前浏览器会话 · 刚刚检查')}</p></div>${a('scan',t('View scan results','查看扫描结果'),'d-primary')}</div><div class="d-security-status"><div><b>!　${t('Your attention is required','需要你处理')}</b><p>${t('3 alerts were reported in the current session. Review the recommended actions below.','当前会话报告了3项警报。请查看下方建议操作。')}</p></div>${a('scan',t('Review alerts','查看警报'),'d-primary')}</div><div class="d-console-stats">${[[t('Device security','设备安全'),t('Attention needed','需要处理'),'!'],[t('Network privacy','网络隐私'),t('Review connection','检查连接'),'◉'],[t('Protection updates','保护更新'),t('Update available','有可用更新'),'↻']].map(([l,s,i],n)=>`<article><span>${i}</span><h2>${l}</h2><p>${s}</p>${a('threat',t('Details →','详情 →'),'d-text-link',{id:n})}</article>`).join('')}</div><div class="d-panel d-console-activity"><h2>${t('Recent activity','最近活动')}</h2><table class="d-table"><thead><tr><th>${t('Time','时间')}</th><th>${t('Activity','活动')}</th><th>${t('Result','结果')}</th></tr></thead><tbody><tr><td>Just now</td><td>${t('Quick web check','快速网页检查')}</td><td>${a('scan',t('3 alerts','3项警报'))}</td></tr><tr><td>Just now</td><td>${t('Protection component','保护组件')}</td><td>${t('Review required','需要检查')}</td></tr><tr><td>Today</td><td>${t('Browser session','浏览器会话')}</td><td>${t('Session active','会话运行中')}</td></tr></tbody></table>${a('support',t('Contact support','联系支持'),'d-text-link')}</div></section></div>`;
